onship", "type": "text"}, {"key": "age", "label": "Age", "type": "number", "whole": true}]}, {"key": "pets", "label": "Do you have any pets?", "type": "radio", "options": ["Yes", "No"], "required": true}, {"key": "pets_describe", "label": "Describe your pets", "type": "textarea", "span": 2, "show_if": {"field": "pets", "op": "equals", "value": "Yes"}}, {"key": "vacating_reason", "label": "Why are you vacating your present residence?", "type": "textarea", "span": 2}]}, {"id": "residence", "heading": "Residence History", "columns": 1, "fields": [{"key": "residences", "label": "Places of residence (current + previous)", "type": "subform", "repeat_label": "Add another address", "subfields": [{"key": "applicant", "label": "Applicant", "type": "dropdown", "options": ["Applicant 1", "Applicant 2"], "required": true}, {"key": "address", "label": "Street address", "type": "text", "required": true, "span": 2}, {"key": "city", "label": "City", "type": "text"}, {"key": "from_date", "label": "From", "type": "date"}, {"key": "to_date", "label": "To", "type": "date"}, {"key": "landlord_name", "label": "Landlord name", "type": "text"}, {"key": "landlord_phone", "label": "Landlord phone", "type": "tel"}, {"key": "rent_paid", "label": "Monthly rent paid", "type": "currency"}, {"key": "reason_leaving", "label": "Reason for leaving", "type": "text", "span": 2}]}]}, {"id": "employment", "heading": "Employment", "columns": 1, "fields": [{"key": "jobs", "label": "Employment history", "type": "subform", "repeat_label": "Add another job", "subfields": [{"key": "applicant", "label": "Applicant", "type": "dropdown", "options": ["Applicant 1", "Applicant 2"], "required": true}, {"key": "employer", "label": "Employer", "type": "text", "required": true, "span": 2}, {"key": "business_address", "label": "Business address", "type": "text", "span": 2}, {"key": "business_phone", "label": "Business phone", "type": "tel"}, {"key": "position", "label": "Position held", "type": "text"}, {"key": "start_date", "label": "Start date", "type": "date"}, {"key": "monthly_income", "label": "Monthly income", "type": "currency"}, {"key": "supervisor", "label": "Supervisor name", "type": "text"}]}]}, {"id": "financial", "heading": "Financial Information", "columns": 2, "fields": [{"key": "bank_name", "label": "Bank name", "type": "text"}, {"key": "bank_branch", "label": "Branch", "type": "text"}, {"key": "obligations", "label": "Monthly financial obligations", "type": "subform", "repeat_label": "Add another obligation", "subfields": [{"key": "creditor", "label": "Payable to", "type": "text", "required": true}, {"key": "monthly_payment", "label": "Monthly amount", "type": "currency", "required": true}, {"key": "balance", "label": "Balance owing", "type": "currency"}]}]}, {"id": "references", "heading": "References", "columns": 1, "fields": [{"key": "references", "label": "Personal references", "type": "subform", "repeat_label": "Add another reference", "subfields": [{"key": "name", "label": "Full name", "type": "text", "required": true}, {"key": "relationship", "label": "Relationship", "type": "text"}, {"key": "phone", "label": "Phone", "type": "tel", "required": true}, {"key": "email", "label": "Email", "type": "email"}, {"key": "years_known", "label": "Years known", "type": "number", "whole": true}]}]}, {"id": "consent", "heading": "Consent & Signature", "columns": 1, "fields": [{"key": "consent_text", "label": "Consent", "type": "heading"}, {"key": "consent_given", "label": "I consent to the collection, use and disclosure of my personal information for the purpose of determining my creditworthiness and suitability as a tenant, including credit checks, employment verification and reference checks. I confirm all statements in this application are true and correct.", "type": "checkbox", "required": true}, {"key": "signature_name", "label": "Type your full name as signature", "type": "text", "required": true}, {"key": "signature_date", "label": "Date", "type": "date", "required